import pytest

@pytest.fixture
def rag():                       # built per test, torn down cleanly
    store = VectorStore(":memory:")
    yield RagPipeline(store)     # yield → teardown runs even on failure
    store.close()

@pytest.mark.parametrize("question,expected", [
    ("What is the refund window?", "30 days"),
    ("Do you ship internationally?", "yes, 40 countries"),
    ("Is there a free tier?", "no free tier"),   # unanswerable → abstain
])
def test_answers_are_grounded(rag, question, expected):
    answer = rag.ask(question)
    assert expected.lower() in answer.lower()

@pytest.mark.parametrize("bad", ["", "a", "x" * 5000])
def test_validation_rejects_garbage(rag, bad):
    with pytest.raises(ValidationError):
        rag.ask(bad)
